SELECT inventory.id, inventory.last_restock, inventory.product_id, inventory.store_id, store_sales.sale_date, store_sales.units, store_sales.product_id store_sale_product_id FROM inventory INNER JOIN store_sales ON inventory.store_id = store_sales.store_id AND inventory.product_id = store_sales.product_id WHERE YEAR(inventory.last_restock) = 2025 AND inventory.quantity BETWEEN 99 AND 124 ORDER BY inventory.product_id;
